// Sounds for device events on the optional buzzer (buzzer.h). Every event can play any sound in
// the library; each has a default and a few suggestions. All of it comes from the sound lab
// (sound_data.h, generated by tools/gen_sounds.js). The pick per event is saved (Settings >
// Sound > Sounds). Call from the UI thread only.
//
// Clicks (knob turn, knob press, letter typed/deleted) are quiet ("soft": a volume step below
// the setting), can be turned off on their own, never cut into another sound, and knob ticks
// are rate-limited so a fast spin doesn't turn into a buzz.
#pragma once

#include "sound_data.h"

namespace sounds {

enum Volume : uint8_t { VOL_OFF, VOL_LOW, VOL_MED, VOL_HIGH };

void begin();  // reads the settings
void play(Event e);
void reflexResult(int ms);  // the reflex time: the speed chirp is higher for a faster time
void preview();             // a short sample at the current volume (after changing it)

Volume volume();
void setVolume(Volume v);
const char *volumeName(Volume v);
bool clicks();  // knob and typing clicks on
void setClicks(bool on);

// The sound per event (Settings > Sound > Sounds). Sounds are indexes into SOUNDS; -1 = none;
// CUSTOM = the event's own sound, sent from the sound lab over USB (one per event).
constexpr int CUSTOM = -3;
int soundFor(Event e);
const char *pickName(Event e);      // the name of what the event plays
bool hasCustom(Event e);
const char *customName(Event e);
void setSound(Event e, int i);
void playSound(int i, Event e = EVENT_COUNT);  // preview one (CUSTOM needs the event), even with clicks off
const char *soundName(int i);       // "No sound" for -1
int changedCount();                 // events not on their default
void resetChoices();                // and forget the sound lab's sounds

// Serial commands from the sound lab (the line after "SND"):
//   ?                        print volume, clicks and every event's pick, then "[sound] end"
//   P <event> <sound|->      pick a built-in sound (or none)
//   C <event> <name>|<repeat>,<gap>,<soft>:f0,f1,ms;...   save the event's own sound and pick it
//   V <0-3>   K <0|1>   R    volume, clicks, reset everything
// Each change answers "[sound] ok" or "[sound] error <why>".
void serialCommand(const char *s);

}  // namespace sounds
